const recalculateManifestCounters = `-- name: RecalculateManifestCounters :one
UPDATE manifests m
SET bag_count = c.bags,
    loose_shipment_count = c.loose,
    total_shipment_count = c.bagged_shipments + c.loose,
    total_piece_count = c.bagged_pieces + c.loose_pieces,
    total_weight_grams = c.bagged_weight + c.loose_weight
FROM (
    SELECT
        (SELECT count(*) FROM manifest_bags WHERE manifest_id = $1 AND status <> 'REMOVED') AS bags,
        (SELECT COALESCE(sum(declared_shipment_count), 0)::int FROM manifest_bags
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS bagged_shipments,
        (SELECT COALESCE(sum(declared_piece_count), 0)::int FROM manifest_bags
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS bagged_pieces,
        (SELECT COALESCE(sum(declared_weight_grams), 0)::bigint FROM manifest_bags
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS bagged_weight,
        (SELECT count(*) FROM manifest_loose_shipments
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS loose,
        (SELECT COALESCE(sum(piece_count), 0)::int FROM manifest_loose_shipments
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS loose_pieces,
        (SELECT COALESCE(sum(weight_grams), 0)::bigint FROM manifest_loose_shipments
          WHERE manifest_id = $1 AND status <> 'REMOVED') AS loose_weight
) c
WHERE m.id = $1
RETURNING m.id, m.public_id, m.organization_id, m.manifest_code, m.status, m.origin_unit_id, m.destination_unit_id, m.trip_id, m.direction, m.bag_count, m.loose_shipment_count, m.total_shipment_count, m.total_piece_count, m.total_weight_grams, m.declared_weight_grams, m.closed_at, m.closed_by_user_id, m.dispatched_at, m.dispatched_by_user_id, m.received_at, m.received_by_user_id, m.reconciled_at, m.closed_contents, m.document_object_key, m.document_generated_at, m.event_sequence, m.remarks, m.metadata, m.created_at, m.updated_at, m.version, m.trip_leg_id
`

